import{_ as a,C as n,o as t,c as r,a2 as i,E as h}from"./chunks/framework.BAQ5ZYJQ.js";const y=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"errand","text":"Run it there as if it were here","tagline":"Same command, same output in your terminal, Ctrl-C included, whether “there” is a container, a server over ssh, a Slurm allocation or a Windows VM. errand sets the place up, syncs the files both ways, and cleans up after itself.","actions":[{"theme":"brand","text":"Quickstart","link":"/guide/start"},{"theme":"alt","text":"What errand is","link":"/guide/what-is-errand"},{"theme":"alt","text":"GitHub","link":"https://github.com/hleclerc/errand"}]},"features":[{"icon":"🧭","title":"Any stack of layers","details":"A conda or uv env, Apptainer or Docker, a server over ssh, a Slurm allocation, a Windows VM. Apptainer in Slurm over ssh is three lines.","link":"/guide/environments","linkText":"Environments"},{"icon":"📊","title":"Live in the browser","details":"errand run -O opens the run's page: its console, progress, curves, images and HTML pages, live, wherever it runs. errand web: every run of every machine, with its parameters and results.","link":"/guide/web","linkText":"errand web"},{"icon":"🛠️","title":"Automatic remote installations","details":"Nothing to install over there, not even errand. The env from its requirements, the image from its recipe: installed where it runs on first use, updated when the declaration changes. What already exists is adopted, never rebuilt.","link":"/guide/upkeep","linkText":"Automatic installations"},{"icon":"🔄","title":"Smart sync","details":"Only what changed crosses, through the connection already open: 0.7 s when nothing did. What a run made over there is never deleted; results, live views and caches come back.","link":"/guide/sync","linkText":"Smart sync"},{"icon":"🗄️","title":"Computed once, everywhere","details":"errand.download fetches a file once, even for a node with no internet. @errand.memo keeps a result by its inputs. Both reach every machine; library caches are kept tidy.","link":"/guide/caching","linkText":"Data and results"},{"icon":"🎛️","title":"A fair share of the machine","details":"A run asks for cores, cards, a share of a card's memory, from the command line or from its own code. It waits its turn; a card is assigned, never just counted.","link":"/guide/machine","linkText":"Sharing a machine"},{"icon":"🛰️","title":"Servers kept while used","details":"errand serve starts a server on demand, never twice, gives its card back to a computation while it rests, and stops it when nobody uses it.","link":"/guide/serve","linkText":"errand serve"},{"icon":"🧹","title":"Nothing left behind","details":"errand status lists what runs on every machine you sent work to. Ctrl-C stops it through every layer. What an agent leaves when it dies, the next one stops.","link":"/guide/status","linkText":"What is running"},{"icon":"💻","title":"Close the laptop","details":"The connection drops, the work goes on over there and its results still come back. --batch gives the shell back at once.","link":"/guide/detached","linkText":"Let it run"},{"icon":"⚡","title":"Warm between commands","details":"Connections, allocations and imports are kept for a while, so the next command starts faster. They give way when someone needs the room.","link":"/guide/agents","linkText":"Agents"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795160929000}`),l={name:"index.md"};function o(p,s,d,k,c,u){const e=n("Term");return t(),r("div",null,[s[0]||(s[0]=i("",4)),h(e,{scene:"stack",caption:"errand run --env cluster train.py. The ssh, the allocation and the container are the three layers declared above."}),s[1]||(s[1]=i("",12))])}const F=a(l,[["render",o]]);export{y as __pageData,F as default};
